<?php $numeric = array_values(array_filter(array_column($rows, 'overall'), fn($value) => $value !== null)); ?>
<div class="academic-student-summary"><article class="glass panel"><div><h2>Draft class average</h2><strong><?php echo $numeric ? esc(grade_display(array_sum($numeric) / count($numeric))) : '—'; ?></strong><p class="muted"><?php echo count($numeric); ?> students with recorded grades</p></div></article><article class="glass panel"><div><h2>Complete gradebooks</h2><strong><?php echo count(array_filter($rows, fn($row) => $row['status'] === 'Complete')); ?>/<?php echo count($students); ?></strong><p class="muted">All periods and weighted assessment categories complete</p></div></article></div>
<div class="academic-analysis-grid"><section class="glass panel academic-analysis-panel"><h2>Grade distribution</h2><?php foreach ($book['config']['scale'] as $band): $count = count(array_filter($rows, fn($row) => $row['scale_label'] === $band['label'])); ?><div class="academic-analysis-row"><span><?php echo esc($band['label']); ?></span><strong><?php echo $count; ?> students</strong><progress max="<?php echo max(1, count($students)); ?>" value="<?php echo $count; ?>" aria-label="<?php echo esc($band['label']); ?> students"></progress></div><?php endforeach; ?></section>
<section class="glass panel academic-analysis-panel"><h2>Grading-period averages</h2><?php foreach ($book['config']['periods'] as $period): $values = []; foreach ($rows as $row) if ($row['periods'][$period['id']]['overall'] !== null) $values[] = $row['periods'][$period['id']]['overall']; $avg = $values ? array_sum($values) / count($values) : null; ?><div class="academic-analysis-row"><span><?php echo esc($period['name']); ?></span><strong><?php echo $avg === null ? 'Not Graded' : esc(grade_display($avg)) . '%'; ?></strong><progress max="100" value="<?php echo esc((string) ($avg ?? 0)); ?>" aria-label="<?php echo esc($period['name']); ?> class average"></progress></div><?php endforeach; ?></section></div>
<section class="glass panel academic-gradebook"><h2>Assessment category averages</h2><div class="academic-table-scroll"><table class="academic-table"><thead><tr><th>Category</th><th>Prelim</th><th>Midterm</th><th>Finals</th></tr></thead><tbody><?php foreach ($book['config']['categories'] as $category): ?><tr><th><?php echo esc($category['name']); ?></th><?php foreach ($book['config']['periods'] as $period): $values = []; foreach ($rows as $row) foreach ($row['periods'][$period['id']]['categories'] as $c) if ($c['id'] === $category['id'] && $c['percentage'] !== null) $values[] = $c['percentage']; ?><td><?php echo $values ? esc(grade_display(array_sum($values) / count($values))) . '%' : 'Not Graded'; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></section>
<section class="glass panel academic-gradebook"><h2>Activity performance</h2><div class="academic-table-scroll"><table class="academic-table"><thead><tr><th>Activity</th><th>Period</th><th>Average</th><th>Recorded scores</th></tr></thead><tbody><?php $performance = []; foreach ($book['items'] as $id => $entry) { if (!empty($entry['archived'])) continue; $values = []; foreach ($rows as $row) if (($row['items'][$id]['percentage'] ?? null) !== null) $values[] = $row['items'][$id]['percentage']; $performance[] = $entry + ['average' => $values ? array_sum($values) / count($values) : null, 'count' => count($values)]; } usort($performance, fn($a, $b) => ($a['average'] ?? INF) <=> ($b['average'] ?? INF)); $performancePage = page_records($performance); foreach ($performancePage['items'] as $entry): ?><tr><th><?php echo esc($entry['name']); ?></th><td><?php echo esc(ucfirst($entry['period_id'] ?? 'Unassigned')); ?></td><td><?php echo esc(grade_display($entry['average'])); ?><?php echo $entry['average'] === null ? '' : '%'; ?></td><td><?php echo $entry['count']; ?>/<?php echo count($students); ?></td></tr><?php endforeach; ?><?php if (!$performance): ?><tr><td colspan="4" class="academic-empty">Add assessments to see activity performance.</td></tr><?php endif; ?></tbody></table></div><?php render_pagination($performancePage); ?></section>
